UPDATE wo_sheet_lock_line
   SET DEL_DATETIME = CURRENT_TIMESTAMP,
       DEL_USER      = #{userKey}
 WHERE LOCK_SEQ = #{lockSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_sheet_lock_line
   SET EXPIRE_DATETIME = CURRENT_TIMESTAMP + (INTERVAL '1' SECOND * CAST(#{ttlSeconds} AS INT)),
       MOD_DATETIME    = CURRENT_TIMESTAMP,
       MOD_USER         = #{userKey}
 WHERE LOCK_SEQ = #{lockSeq}
   AND LOCK_USER = #{userKey}
   AND DEL_DATETIME IS NULL
